intro:
Searches for the next occurrence of pattern in the underlying view. Equivalent to:

auto [b, e] = ranges::search(ranges::subrange(it, ranges::end(base_)), pattern_);



if (b != ranges::end(base_) and ranges::empty(pattern_))

{

    ++b;

    ++e;

}



return {b, e};

examples.code:
#include <ranges>
#include <string_view>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::string_view input = "one,two";
    auto split = std::views::split(input, ',');
    auto first = split.begin();
    auto end = split.end();
    assert(first != end);
    auto word = *first;
    assert(std::ranges::distance(word) == 3);
    ++first;
    assert(first != end);
    auto lazy = std::views::lazy_split(input, ',');
    auto outer = lazy.begin();
    auto inner = (*outer).begin();
    assert(*inner == 'o');
    ++inner;
    assert(*inner == 'n');
    ++outer;
    assert(*(*outer).begin() == 't');
}
